create table if not exists public.enterprise_partner_networks (id uuid primary key default gen_random_uuid(), owner_business_id uuid not null references public.businesses(id) on delete cascade, name text not null, enabled boolean not null default true, created_at timestamptz not null default now());
create table if not exists public.enterprise_partner_network_members (id uuid primary key default gen_random_uuid(), network_id uuid not null references public.enterprise_partner_networks(id) on delete cascade, partner_business_id uuid not null references public.businesses(id) on delete cascade, status text not null default 'active' check(status in ('invited','active','paused','removed')), created_at timestamptz not null default now(), unique(network_id,partner_business_id));
create table if not exists public.enterprise_partner_network_metrics (id uuid primary key default gen_random_uuid(), network_id uuid not null references public.enterprise_partner_networks(id) on delete cascade, metric_date date not null, visits bigint not null default 0, check_ins bigint not null default 0, reviews bigint not null default 0, preferred_uses bigint not null default 0, access_redemptions bigint not null default 0, promotion_redemptions bigint not null default 0, unique(network_id,metric_date));
create index if not exists enterprise_partner_network_members_network_idx on public.enterprise_partner_network_members(network_id,status);
create index if not exists enterprise_partner_network_metrics_network_date_idx on public.enterprise_partner_network_metrics(network_id,metric_date desc);
alter table public.enterprise_partner_networks enable row level security;
alter table public.enterprise_partner_network_members enable row level security;
alter table public.enterprise_partner_network_metrics enable row level security;
create or replace function public.get_enterprise_partner_network(p_network_id uuid,p_start date default current_date-30,p_end date default current_date) returns table(network_id uuid,network_name text,partner_count bigint,visits bigint,check_ins bigint,reviews bigint,preferred_uses bigint,access_redemptions bigint,promotion_redemptions bigint) language sql security definer set search_path=public as $$ select n.id,n.name,count(distinct m.partner_business_id),coalesce(sum(x.visits),0),coalesce(sum(x.check_ins),0),coalesce(sum(x.reviews),0),coalesce(sum(x.preferred_uses),0),coalesce(sum(x.access_redemptions),0),coalesce(sum(x.promotion_redemptions),0) from enterprise_partner_networks n left join enterprise_partner_network_members m on m.network_id=n.id and m.status='active' left join enterprise_partner_network_metrics x on x.network_id=n.id and x.metric_date between p_start and p_end where n.id=p_network_id and n.owner_business_id in(select business_id from public.business_members where user_id=auth.uid()) group by n.id,n.name $$;
revoke all on function public.get_enterprise_partner_network(uuid,date,date) from public,anon;
grant execute on function public.get_enterprise_partner_network(uuid,date,date) to authenticated;
create or replace function public.create_enterprise_partner_network(p_name text) returns public.enterprise_partner_networks language plpgsql security definer set search_path=public as $$ declare b uuid; n public.enterprise_partner_networks; begin select business_id into b from public.business_members where user_id=auth.uid() limit 1; if b is null then raise exception 'business membership required'; end if; if not exists(select 1 from public.businesses where id=b and lower(business_tier::text) in ('fleet','enterprise')) then raise exception 'Fleet or Enterprise plan required'; end if; insert into enterprise_partner_networks(owner_business_id,name) values(b,p_name) returning * into n; return n; end $$;
revoke all on function public.create_enterprise_partner_network(text) from public,anon;
grant execute on function public.create_enterprise_partner_network(text) to authenticated;
